<?php ob_start(); ?><h1>Process #<?= (int)$row['id'] ?></h1><p><a href="<?= site_url('admin/operations') ?>">← Back to reports</a></p><section><h2>Process</h2><p>Sales order: <?= esc($row['so_number'] ?? '—') ?> · Customer: <?= esc($row['customer_name'] ?? '—') ?> · Batch: <?= esc($row['batch_qty'] ?? '—') ?></p><p>Machine: <?= esc($row['machine_code'].' '.$row['machine_name']) ?> · <?= esc($row['sector_name'].' / '.$row['activity_name']) ?></p><p>Supervisor: <?= esc($row['supervisor_name']) ?> · Status: <?= esc($row['status']) ?></p><p>Started <?= esc($row['started_at'] ?? '—') ?> · Ended <?= esc($row['ended_at'] ?? '—') ?></p><p>Passed <?= esc($row['qty_passed'] ?? '—') ?> · Rejected <?= esc($row['qty_rejected'] ?? '—') ?></p><p>Remarks: <?= nl2br(esc($row['remarks'] ?? '')) ?></p></section><?php foreach (['operators'=>'Operators','qc'=>'QC inspections','problems'=>'Problems','pics'=>'PIC history'] as $key=>$heading): ?><section><h2><?= esc($heading) ?></h2><?php if (!$row[$key]): ?><p class="muted">No entries.</p><?php else: ?><table><?php foreach ($row[$key] as $entry): ?><tr><?php foreach ($entry as $value): ?><td><?= esc((string)$value) ?></td><?php endforeach ?></tr><?php endforeach ?></table><?php endif ?></section><?php endforeach ?><?php $content=ob_get_clean(); echo view('admin/shell',['title'=>$title,'content'=>$content]); ?>
